27	const PROCESSING_FEE = 5;
28	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
29	
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
40	
41	const policyBasePremium = (items: Item[]): number =>
42	  items.reduce((total, item) => total + basePremiumOf(item), 0);
43	
44	// The MHPCO rounds in its own favour: premiums up, payouts down.
45	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
46	
47	const quote = (step: Step): QuoteResult => {
48	  const basePremium = policyBasePremium(step.items);
49	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
50	  const modifiedPremium = basePremium + firstInsuranceSurcharge;
51	
52	  return {
53	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
54	  };
55	};
56	
57	export const runScenario = (scenario: Scenario): ScenarioResult => ({
58	  results: scenario.steps.map(quote),
59	});
